/**
 * Pre-generated Georgian copy for synastry aspect detail modals.
 *
 * Every (aspect-kind × body-pair) combo gets a positive paragraph (what
 * the energy gives the relationship) and a negative paragraph (what to
 * watch for). The deterministic templating in `synastry-interpretation`
 * was producing grammatically rough sentences and only one perspective,
 * this layer replaces it with LLM-generated prose covering both sides.
 *
 * Content is generated by `scripts/generate-synastry-aspects.mjs` and
 * committed into the repo so the public site has zero LLM dependency at
 * build/runtime.
 */

import rawContent from "./seo/synastry-aspects.json";
import rawContentEn from "./seo/synastry-aspects-en.json";
import type { AspectKind } from "./aspects";

export type AspectDetailContent = {
  positive: string;
  negative: string;
  takeaway: string;
};

/**
 * Canonical body order, same as `BODY_KEYS` in astrology-local with
 * the angles appended. Used to deterministically sort body pairs so
 * (sun, moon) and (moon, sun) resolve to the same JSON key.
 */
export const BODY_ORDER = [
  "sun",
  "moon",
  "mercury",
  "venus",
  "mars",
  "jupiter",
  "saturn",
  "uranus",
  "neptune",
  "pluto",
  "chiron",
  "ascendant",
  "midheaven",
] as const;

export type BodyKey = (typeof BODY_ORDER)[number];

const BODY_INDEX: Record<string, number> = Object.fromEntries(
  BODY_ORDER.map((b, i) => [b, i])
);

export function aspectDetailKey(
  kind: AspectKind,
  a: string,
  b: string
): string {
  const ia = BODY_INDEX[a] ?? -1;
  const ib = BODY_INDEX[b] ?? -1;
  const [first, second] = ia <= ib ? [a, b] : [b, a];
  return `${kind}:${first}-${second}`;
}

const CONTENT = rawContent as Record<string, AspectDetailContent>;
const CONTENT_EN = rawContentEn as Record<string, AspectDetailContent>;

import type { UserLocale } from "./i18n/user-locale";

export function aspectDetailContent(
  kind: AspectKind,
  a: string,
  b: string,
  locale: UserLocale = "ka"
): AspectDetailContent | null {
  const table = locale === "en" ? CONTENT_EN : CONTENT;
  return table[aspectDetailKey(kind, a, b)] ?? null;
}

/** All keys present in the generated JSON. Useful for the generator script. */
export function loadedAspectKeys(): string[] {
  return Object.keys(CONTENT);
}
